import {families,formatCatalog,mappingRoles,labels,visibleFamily,bytes} from './ingestion-catalog.js';
import {browserRead,loadCloud,nativeImport,commitNative,cancelNative,nativePreview,importLocal,commitLocal,pollImport,resumableUpload} from './ingestion-client.js';
import * as repository from './project-repository.js';
import {api} from './auth.js';

let lastProject=null;
let host,tab='sources',query='',typeFilter='',statusFilter='',loading=false,lastCloud=0,refreshTimer;
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=value=>value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):String(value);
const short=value=>{const result=text(value);return esc(result.length>160?result.slice(0,160)+'…':result);};
const nameOf=id=>families.find(f=>f.id===id)?.name||id;
export function configureData(context){host=context;}
function context(){return host.getState().ingestion||{imports:[],datasets:[],templates:[]};}
const datasetKey=d=>`${d.importId}:${d.id}`;
export function dataPageView(route){
 if(route==='wells')tab='wells';if(route==='documents'){tab='sources';typeFilter='documents';}
 const state=host.getState(),project=host.getProject(),data=context();
 const matching=item=>(text(item.name||item.id)+' '+text(item.well||'')).toLowerCase().includes(query.toLowerCase())&&(!typeFilter||(item.family||item.type)===typeFilter)&&(!statusFilter||(item.status||'').includes(statusFilter));
 const files=state.files||[],datasets=data.datasets||[],imports=data.imports||[];
 const active=datasets.filter(d=>d.active!==false);
 const tabs=[['sources','Sources',files.length],['wells','Wells',(state.wellDrafts||[]).length],['datasets','Datasets',active.length],['history','Import history',imports.length]];
 let body;
 if(tab==='sources')body=table(['Original source','Data type','Well / survey','Status','Size',''],files.filter(matching).map(f=>`<tr><td><strong>${esc(f.name)}</strong><small>${f.external?'Linked external original':f.sha256?'SHA-256 verified':'Original retained'}</small></td><td>${esc(nameOf(f.type))}</td><td>${esc(f.well||'Not assigned')}</td><td>${pill(f.status||'Stored original · classification required')}</td><td class="mono">${typeof f.size==='number'?bytes(f.size):esc(f.size)}</td><td><button data-source="${esc(f.id||f.name)}">Inspect</button></td></tr>`),'No sources yet','Add original files, then confirm their identity, mapping and references.');
 else if(tab==='datasets')body=table(['Dataset','Data type','Records','Well','Status',''],active.filter(matching).map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.parserVersion||'')} · original linked</small></td><td>${esc(nameOf(d.family))}</td><td class="mono">${Number(d.rowCount||0).toLocaleString()}</td><td>${esc(d.well||'Not assigned')}</td><td>${pill(d.status)}</td><td><button data-dataset="${esc(datasetKey(d))}">Preview</button></td></tr>`),'No imported datasets','Originals become datasets only after inspection and your final confirmation.');
 else if(tab==='wells')body=table(['Well identifier','Evidence','Registration state',''],(state.wellDrafts||[]).filter(w=>w.id.toLowerCase().includes(query.toLowerCase())).map(w=>`<tr><td><strong>${esc(w.id)}</strong></td><td>${datasets.filter(d=>d.well===w.id).length} datasets</td><td>${pill(w.status)}</td><td><button data-well-evidence="${esc(w.id)}">View evidence</button></td></tr>`),'No wells registered','Confirm well identities while importing logs, headers or survey evidence.');
 else body=table(['Import','Data type','Sources','State',''],imports.filter(matching).map(r=>`<tr><td><strong>${esc(new Date(r.createdAt).toLocaleString())}</strong><small>${esc(r.id.slice(0,16))}</small></td><td>${esc(nameOf(r.family))}</td><td>${r.assets?.length||0}</td><td>${pill(r.status)}</td><td><button data-import="${esc(r.id)}">${['inspecting','importing','uploading'].includes(r.status)?'View progress':'Review'}</button></td></tr>`),'Your import history starts here','Completed imports, warnings and retained originals stay traceable.');
 return `<section class="data-library"><div class="data-page-head"><div><div class="study-kicker">PROJECT EVIDENCE</div><h1>Data</h1><p>Keep the originals. Confirm the meaning. Import with confidence.</p></div><div class="actions"><button id="data-formats">Supported formats</button><button class="primary" data-action="upload">${host.icon('plus')}Add data</button></div></div><div class="data-summary"><span><strong>${files.length}</strong> originals</span><span><strong>${active.length}</strong> datasets</span><span><strong>${active.filter(d=>d.status==='retained/unresolved').length}</strong> need reference review</span><span>${project.storage==='cloud'?'Cloud storage':project.storage==='local'?'Local folder':'Portable project'}${data.quota?` · ${bytes(data.quota.used)} / ${bytes(data.quota.projectLimit)}`:''}</span></div><div class="data-surface"><nav class="data-tabs" aria-label="Data sections">${tabs.map(([id,title,count])=>`<button data-data-section="${id}" aria-current="${id===tab?'page':'false'}">${title}<span>${count}</span></button>`).join('')}</nav><div class="data-filter-bar"><label class="data-search">${host.icon('search')}<input id="data-query" aria-label="Search project data" placeholder="Search by name or well…" value="${esc(query)}"></label>${tab!=='wells'?`<select id="data-type-filter" aria-label="Filter data type"><option value="">All data types</option>${families.map(f=>`<option value="${f.id}" ${typeFilter===f.id?'selected':''}>${f.name}</option>`).join('')}</select><select id="data-status-filter" aria-label="Filter import status"><option value="">All states</option>${['ready','retained','awaiting','failed','cancelled','inspecting'].map(v=>`<option ${statusFilter===v?'selected':''}>${v}</option>`).join('')}</select>`:''}<button id="refresh-data" class="quiet">${loading?'Refreshing…':'Refresh'}</button></div>${body}</div><p class="data-footnote">Ready means imported—not scientifically approved. Unconfirmed units, coordinates and datums remain visible.</p></section>`;
}
function table(headers,rows,title,description){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:`<div class="data-empty"><span>${host.icon('file')}</span><h2>${title}</h2><p>${description}</p><button data-action="upload">Add data ${host.icon('arrow')}</button></div>`;}
function pill(status){return `<span class="data-status ${/failed|blocking/.test(status)?'failed':/ready/.test(status)?'ready':'neutral'}">${esc(status||'Not classified')}</span>`;}
export function bindDataPage(){if(lastProject!==host.getProject()?.id){lastProject=host.getProject()?.id;lastCloud=0;}
 document.querySelectorAll('[data-data-section]').forEach(b=>b.onclick=()=>{tab=b.dataset.dataSection;host.render();});
 $('#data-query')?.addEventListener('input',e=>{query=e.target.value;const position=e.target.selectionStart;host.render();$('#data-query').focus();$('#data-query').setSelectionRange(position,position);});
 $('#data-type-filter')?.addEventListener('change',e=>{typeFilter=e.target.value;host.render();});$('#data-status-filter')?.addEventListener('change',e=>{statusFilter=e.target.value;host.render();});
 $('#data-formats')?.addEventListener('click',()=>host.modal('Format coverage',`<p class="sub">Coverage depends on the documented version and selected storage. Closed variants require conversion; no format is accepted by extension alone.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Format</th><th>Versions / boundaries</th><th>Cloud</th><th>Local</th></tr></thead><tbody>${formatCatalog.map(f=>`<tr><td>${esc(f.name)}</td><td>${esc(f.versions)}</td><td>${esc(f.server)}</td><td>${esc(f.local)}</td></tr>`).join('')}</tbody></table></div>`));
 $('#refresh-data')?.addEventListener('click',()=>refreshData(true));
 document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceDetail(b.dataset.source));
 document.querySelectorAll('[data-dataset]').forEach(b=>b.onclick=()=>datasetDetail(b.dataset.dataset));
 document.querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>reviewImport(b.dataset.import));
 document.querySelectorAll('[data-well-evidence]').forEach(b=>b.onclick=()=>{query=b.dataset.wellEvidence;tab='datasets';host.render();});
 if(host.getProject()?.storage==='cloud'&&Date.now()-lastCloud>10000&&!loading)refreshData();
}
async function refreshData(force=false){
 const project=host.getProject();if(!project||project.storage!=='cloud')return;
 loading=true;try{const data=await loadCloud(project);if(host.getProject()?.id!==project.id)return;host.getState().ingestion=data;lastCloud=Date.now();loading=false;host.render();if(data.imports.some(r=>['inspecting','importing'].includes(r.status))){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refreshData(),5000);}}catch(error){host.toast(error.message);}finally{loading=false;}
}
async function sourceDetail(id){
 const source=host.getState().files.find(f=>(f.id||f.name)===id);if(!source)return;
 host.modal('Original source',`<h3>${esc(source.name)}</h3><dl class="data-details"><dt>Size</dt><dd>${typeof source.size==='number'?bytes(source.size):esc(source.size)}</dd><dt>Storage</dt><dd>${source.external?'Linked external file':'Retained original'}</dd><dt>Fingerprint</dt><dd class="mono">${esc(source.sha256||'Computed during inspection')}</dd><dt>Status</dt><dd>${esc(source.status||'Classification required')}</dd></dl><div class="actions"><button id="source-download">Download original</button><button id="source-classify" class="primary">Import / classify</button></div>`);
 $('#source-download').onclick=async()=>{try{if(host.getProject().storage==='cloud'&&source.size>128*1024**2){const result=await api(`/api/projects/${host.getProject().id}/files/${source.id}/download-link`);const link=document.createElement('a');link.href=result.url;link.rel='noreferrer';link.click();}else host.download(source.name,await repository.source(host.getProject(),source));}catch(error){host.toast(error.message);}};
 $('#source-classify').onclick=()=>{ $('#dialog').close();openImporter({existing:source});};
}
function previewTable(dataset){return `<div class="data-preview-meta"><span>${dataset.rowCount.toLocaleString()} records</span><span>${dataset.columns.length} columns</span><span>${esc(dataset.metadata?.format||'')}</span></div><div class="table-wrap data-preview"><table><thead><tr>${dataset.columns.slice(0,16).map(c=>`<th>${esc(c.mnemonic)}<small>${esc(c.effectiveUnit||c.unit||'Unit unconfirmed')}</small></th>`).join('')}</tr></thead><tbody>${dataset.preview.slice(0,30).map(row=>`<tr>${row.slice(0,16).map(v=>`<td>${short(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${curvePlot(dataset)}<details class="source-metadata"><summary>Source metadata and references</summary><pre>${esc(JSON.stringify(dataset.metadata||{},null,2))}</pre></details>`;}
function curvePlot(dataset){if(dataset.columns.length<2||dataset.family!=='logs')return '';const data=dataset.preview.filter(row=>typeof row[0]==='number'&&typeof row[1]==='number');if(data.length<2)return '';const xs=data.map(r=>r[1]),ys=data.map(r=>r[0]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);const pts=data.map(r=>`${40+(r[1]-xmin)/(xmax-xmin||1)*500},${20+(r[0]-ymin)/(ymax-ymin||1)*180}`).join(' ');return `<div class="data-curve"><p>Source preview · ${esc(dataset.columns[1].mnemonic)} against ${esc(dataset.columns[0].mnemonic)} · first ${data.length} valid samples</p><svg viewBox="0 0 580 230" role="img" aria-label="Imported source curve preview"><path d="M40 15v185h510" stroke="#a8b9b1" fill="none"/><polyline points="${pts}" stroke="#087c73" stroke-width="1.6" fill="none"/><text x="40" y="220">${xmin}</text><text x="480" y="220">${xmax}</text></svg></div>`;}
async function datasetDetail(key){const [importId,id]=key.split(':');const dataset=context().datasets.find(d=>d.id===id&&d.importId===importId);if(!dataset)return;try{const result=host.getProject().storage==='cloud'?await nativePreview(host.getProject(),importId,id):dataset;if(dataset.activeColumns){const indices=result.columns.map((c,i)=>dataset.activeColumns.includes(c.id)?i:-1).filter(i=>i>=0);result.columns=indices.map(i=>result.columns[i]);result.preview=result.preview.map(row=>indices.map(i=>row[i]));}host.modal('Dataset preview',`<h3>${esc(dataset.name)}</h3><p class="sub">Imported evidence · scientific approval has not been granted.</p>${previewTable(result)}${issuesView(dataset.issues||[])}`);}catch(error){host.toast(error.message);}}
function issuesView(issues){return issues.length?`<div class="import-issues">${issues.slice(0,80).map(i=>`<div class="import-issue ${i.severity==='blocking'?'blocking':''}"><strong>${i.severity==='blocking'?'Resolve before activation':'Review'}</strong><p>${esc(i.message)}</p></div>`).join('')}</div>`:'<div class="import-clear">No import validation issues found. Scientific review is separate.</div>';}

export async function openImporter({existing}={}){
 const project=host.getProject(),workspace=host.getState();
 if(!project||project.storage==='legacy'){host.toast('Choose a storage destination in Project settings before importing.');return;}
 await host.flush();
 const wizard={step:0,family:project.workflows?.includes('petrophysics')?'logs':project.workflows?.includes('seismic')?'seismic':'documents',assets:[],options:{references:{},mapping:{},units:{},perFile:{}},preview:null,busy:false,record:null,controller:new AbortController(),warnings:false};
 if(existing){try{if(project.storage==='cloud'){wizard.assets=[{file:{name:existing.name,size:existing.size},existingId:existing.id}];wizard.nativeNotice='Detailed inspection uses the retained Cloud original without downloading or uploading another copy.';}else{const file=await repository.source(project,existing);wizard.assets=[{file:new File([file],existing.name),existingId:existing.id}];}}catch(error){host.toast(error.message);return;}}
 const dialog=$('#dialog');
 function capture(){const form=$('#ingestion-form');if(!form)return;const fields=new FormData(form);
  if(wizard.step===0)wizard.family=String(fields.get('family')||wizard.family);
  if(wizard.step===2){for(const asset of wizard.assets){const well=String(fields.get('well:'+asset.file.name)||'').trim();wizard.options.perFile[asset.file.name]={well,createWell:fields.get('create:'+asset.file.name)==='on'};}wizard.options.run=String(fields.get('run')||'');}
  if(wizard.step===3){for(const role of mappingRoles[wizard.family]||[])wizard.options.mapping[role]=String(fields.get('mapping:'+role)||'');for(const key of ['depthUnit','depthReference','crs','northReference','verticalDatum','timeConvention','timeUnit','domain','angleUnit','coordinateOrder'])wizard.options.references[key]=String(fields.get('ref:'+key)||'');for(const key of ['delimiter','encoding','sheet','null','endian','surfaceFormat','jsonPath'])wizard.options[key]=String(fields.get(key)||'');wizard.options.headerRow=Number(fields.get('headerRow')||1);wizard.options.widths=String(fields.get('widths')||'').split(',').map(Number).filter(n=>n>0);wizard.options.hdfPaths=String(fields.get('hdfPaths')||'').split(',').map(s=>s.trim()).filter(Boolean);wizard.options.surveyMethod=String(fields.get('surveyMethod')||'angles');for(const column of wizard.preview?.columns||[])wizard.options.units[column.id.split('-')[1]]=String(fields.get('unit:'+column.id)||'');wizard.options.headerBytes={};for(const key of ['inline','crossline','x','y','scalar']){const val=fields.get('byte:'+key);if(val)wizard.options.headerBytes[key]=Number(val);}}
 }
 const select=(name,label,values,value='',optional=true)=>`<label class="field">${label}<select name="${name}">${optional?'<option value="">Unconfirmed / choose later</option>':''}${values.map(v=>{const [id,title]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${value===id?'selected':''}>${esc(title)}</option>`;}).join('')}</select></label>`;
 const input=(name,label,value='',placeholder='')=>`<label class="field">${label}<input name="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}"></label>`;
 function close(event){event?.preventDefault();if(wizard.busy){host.toast('Import continues in the background. Use Cancel import to stop it.');return;}if(wizard.assets.length&&!wizard.record){capture();const body=dialog.querySelector('.dialog-body');body.innerHTML='<h3>Leave this import setup?</h3><p>No new Cloud transfer has started. Selected files and settings will be cleared.</p><div class="actions"><button id="import-keep" class="primary">Keep editing</button><button id="import-leave">Leave setup</button></div>';$('#import-keep').onclick=draw;$('#import-leave').onclick=()=>dialog.close();}else dialog.close();}
 async function preflight(){
  wizard.busy=true;if($('#import-feedback'))$('#import-feedback').textContent='Reading source headers and previews…';wizard.previews={};wizard.nativeNotice='';
  for(const asset of wizard.assets){if(/\.(shx|dbf|prj|cpg|h5)$/i.test(asset.file.name))continue;try{const result=await browserRead(asset.file,wizard.family,{...wizard.options,...wizard.options.perFile[asset.file.name]},{previewOnly:true,signal:wizard.controller.signal});const preview=result.datasets[0];wizard.previews[asset.file.name]=preview;wizard.preview||=preview;if(preview?.well&&!wizard.options.perFile[asset.file.name])wizard.options.perFile[asset.file.name]={well:preview.well,createWell:!(workspace.wellDrafts||[]).some(w=>w.id===preview.well)};}catch(error){wizard.nativeNotice=error.message;}}
  wizard.busy=false;draw();
 }

 function draw(){
  if(dialog.open)dialog.close();
  const refs=wizard.options.references,steps=['Type','Files','Identity','Mapping','Review','Import'];
  let body='';
  if(wizard.step===0)body=`<h3>What would you like to add?</h3><p class="sub">Choose the meaning of the data first. We will check the file format next.</p><input id="import-type-search" aria-label="Find a data type" placeholder="Find logs, deviation, seismic…"><div class="import-family-list">${['Wells','Seismic','Spatial / models','Documents'].map(group=>`<section><h4>${group}</h4>${families.filter(f=>f.group===group).map(f=>`<label class="import-family ${!visibleFamily(f,project)?'unavailable':''}"><input name="family" type="radio" value="${f.id}" ${wizard.family===f.id?'checked':''} ${!visibleFamily(f,project)?'disabled':''}><span><strong>${f.name}</strong><small>${visibleFamily(f,project)?f.formats:'Enable the relevant workflow in Project settings'}</small></span></label>`).join('')}</section>`).join('')}</div>`;
  if(wizard.step===1)body=`<h3>Select your source files</h3><p class="sub">${esc(nameOf(wizard.family))} · include companion files in the same selection.</p><label class="import-drop">${host.icon('upload')}<strong>Choose files</strong><span>Originals are preserved in ${project.storage==='cloud'?'your Cloud project':'your selected Local storage'}.</span><input id="import-files" type="file" multiple ${existing?'disabled':''}></label>${project.storage==='local'&&typeof window.showOpenFilePicker==='function'?'<button id="import-linked-picker" type="button">Choose linked local files</button><p class="sub">Linked files stay in place. Keep their original location available.</p>':''}${context().templates?.some(t=>t.family===wizard.family)?'<label class="field">Apply saved mapping template<select id="import-template-select"><option value="">Start with source suggestions</option>'+context().templates.filter(t=>t.family===wizard.family).map(t=>'<option value="'+esc(t.id)+'">'+esc(t.name)+'</option>').join('')+'</select></label>':''}<div class="import-file-list">${wizard.assets.map(a=>`<div><span><strong>${esc(a.file.name)}</strong><small>${bytes(a.file.size)}${a.existingId?' · already retained':a.handle?' · linked file':''}</small></span></div>`).join('')}</div><p class="sub">Cloud: up to 10 GiB per file / 50 GiB per project. Portable projects require smaller files or a folder bundle.</p><p id="import-feedback" role="status"></p>`;
  if(wizard.step===2)body=`<h3>Confirm the destination</h3><p class="sub">Match each source to its well, or leave it unassigned if it contains survey/model evidence. File names never establish a well match.</p><datalist id="import-wells">${(workspace.wellDrafts||[]).map(w=>`<option value="${esc(w.id)}">`).join('')}</datalist>${wizard.assets.filter(a=>!/\.(shx|dbf|prj|cpg|h5)$/i.test(a.file.name)).map(a=>`<section class="import-well-match"><strong>${esc(a.file.name)}</strong><label class="field">Well identifier <small>${wizard.preview?.metadata?.headers?'Detected header is a suggestion; confirm it here.':'Optional for multi-well / survey data'}</small><input name="well:${esc(a.file.name)}" list="import-wells" maxlength="100" value="${esc(wizard.options.perFile[a.file.name]?.well||'')}"></label><label class="layer"><input type="checkbox" name="create:${esc(a.file.name)}" ${wizard.options.perFile[a.file.name]?.createWell?'checked':''}>Create this well if it does not exist</label></section>`).join('')}${input('run','Acquisition / run / survey name',wizard.options.run||'','Optional source grouping')}`;
  if(wizard.step===3){const columns=wizard.preview?.columns||[],refsNeeded=['logs','deviation','tops','checkshots','core','pressure','arrays'].includes(wizard.family);body=`<h3>Confirm mapping and references</h3><p class="sub">Suggestions are editable. Unknown values remain unresolved and cannot silently become validated scientific inputs.</p>${wizard.nativeNotice?`<div class="note">${esc(wizard.nativeNotice)}${project.storage==='cloud'?' Detailed native inspection runs after you confirm the upload.':' The original can be retained; a supported export is needed to create a dataset.'}</div>`:''}<div class="form-grid">${(mappingRoles[wizard.family]||[]).map(role=>select('mapping:'+role,labels[role],columns.map((c,i)=>[String(i),c.mnemonic+' · '+(c.unit||'unit unknown')]),wizard.options.mapping[role]||'')).join('')}</div><details open><summary>Source references</summary><div class="form-grid">${refsNeeded?select('ref:depthReference','Depth reference',['MD','TVD','TVDSS','TST'],refs.depthReference)+select('ref:depthUnit','Depth units',['m','ft'],refs.depthUnit):''}${wizard.family==='deviation'?select('surveyMethod','Survey columns',[['angles','MD / inclination / azimuth'],['coordinates','MD / X / Y / Z']],wizard.options.surveyMethod||'angles',false)+select('ref:northReference','Azimuth north reference',['True north','Grid north','Magnetic north'],refs.northReference)+select('ref:angleUnit','Angle units',['degrees','radians'],refs.angleUnit):''}${['checkshots','seismic'].includes(wizard.family)?select('ref:timeConvention','Time convention',['One-way time','Two-way time'],refs.timeConvention)+select('ref:timeUnit','Time units',['ms','s'],refs.timeUnit):''}${['seismic','surfaces','models'].includes(wizard.family)?select('ref:domain','Vertical domain',['Time','Depth'],refs.domain):''}${input('ref:crs','Source CRS / datum',refs.crs||'','For example EPSG:32632; do not guess')}${input('ref:verticalDatum','Elevation / vertical datum',refs.verticalDatum||'','KB, MSL or documented source datum')}${select('ref:coordinateOrder','Coordinate order',['X / Y','Longitude / latitude','Latitude / longitude'],refs.coordinateOrder)}</div></details><details><summary>File layout and advanced options</summary><div class="form-grid">${input('headerRow','Header row (1-based)',wizard.options.headerRow||1)}${select('delimiter','Column separator',[[',','Comma'],[';','Semicolon'],['\t','Tab'],['whitespace','Whitespace']],wizard.options.delimiter)}${input('widths','Fixed-width sizes',wizard.options.widths?.join(',')||'','For example 10,12,12')}${select('encoding','Text encoding',['utf-8','windows-1252','latin1'],wizard.options.encoding||'utf-8',false)}${input('sheet','Excel worksheet',wizard.options.sheet||'','First worksheet if blank')}${input('null','Missing-value sentinel',wizard.options.null??'','Preserve source nulls')}${input('jsonPath','JSON record-array path',wizard.options.jsonPath||'','For example data.records')}${input('hdfPaths','HDF5 dataset paths',wizard.options.hdfPaths?.join(',')||'','Comma-separated paths')}${select('endian','Seismic byte order',['big','little'],wizard.options.endian||'big',false)}${['inline','crossline','x','y','scalar'].map(key=>input('byte:'+key,'Trace header byte: '+key,wizard.options.headerBytes?.[key]||({inline:189,crossline:193,x:181,y:185,scalar:71})[key])).join('')}${input('surfaceFormat','Surface dialect',wizard.options.surfaceFormat||'','guess, irap_ascii, irap_binary, zmap_ascii')}</div></details>${columns.length?`<details><summary>Confirm curve / column units</summary><div class="form-grid">${columns.map(c=>input('unit:'+c.id,c.mnemonic+' · source '+(c.unit||'unknown'),wizard.options.units[c.id.split('-')[1]]||'','Leave blank to retain unconfirmed units')).join('')}</div></details>`:''}`;}
  if(wizard.step===4)body=`<h3>Review before import</h3><p class="sub">${project.storage==='cloud'?'Clicking Upload & inspect sends these originals to your private Cloud project. Activation requires a second review after native inspection.':'Parsing and originals remain on this device. No Local file content is uploaded.'}</p><dl class="data-details"><dt>Data type</dt><dd>${esc(nameOf(wizard.family))}</dd><dt>Originals</dt><dd>${wizard.assets.length} files · ${bytes(wizard.assets.reduce((n,a)=>n+a.file.size,0))}</dd><dt>Storage</dt><dd>${project.storage==='cloud'?'Private Cloud storage':project.storage==='local'?wizard.options.linkOriginals?'Linked Local originals':'Local project folder':'Portable project file'}</dd><dt>Version handling</dt><dd>Preserve originals; create independent runs. Exact duplicates are skipped during inspection.</dd></dl>${wizard.preview?`<details><summary>Source preview · first records</summary>${previewTable(wizard.preview)}</details>`:''}${wizard.nativeNotice?`<p class="note">${esc(wizard.nativeNotice)}</p>`:''}<label class="layer"><input id="import-authority" type="checkbox" required>I have authority to use these files and have reviewed their destination and source references.</label>`;
  if(wizard.step===5)body=`<h3>${wizard.busy?'Import in progress':wizard.record?.committedAt?'Import recorded':'Review inspected data'}</h3><p id="import-feedback" role="status">${wizard.busy?'Retaining originals and inspecting evidence…':'Review the reader outcome before activation.'}</p>${wizard.record?recordView(wizard.record):'<div class="import-progress"><span></span></div>'}`;
  host.modal('Add data',`<div class="import-steps" aria-label="Import progress">${steps.map((title,i)=>`<span class="${i===wizard.step?'current':i<wizard.step?'complete':''}" ${i===wizard.step?'aria-current="step"':''}>${i+1}<small>${title}</small></span>`).join('')}</div><form id="ingestion-form">${body}<p id="import-error" class="setup-error" role="alert"></p><div class="setup-footer"><button id="import-back" type="button">${wizard.step===5?'Close':wizard.step?'Back':'Cancel'}</button><div class="actions">${wizard.busy?'<button type="button" id="cancel-import">Cancel import</button>':''}${wizard.step<5?`<button type="submit" class="primary">${wizard.step===4?project.storage==='cloud'?'Upload & inspect':'Retain & inspect':'Continue'}</button>`:''}</div></div></form>`);
  dialog.classList.add('ingestion-dialog');dialog.oncancel=close;dialog.querySelector('[data-close]').onclick=close;
  $('#import-back').onclick=()=>{if(wizard.busy){host.toast('Use Cancel import to stop this import.');return;}capture();if(wizard.step===5){dialog.close();host.render();return;}if(wizard.step){wizard.step--;draw();}else close();};
  $('#import-type-search')?.addEventListener('input',e=>{for(const item of dialog.querySelectorAll('.import-family'))item.hidden=!item.textContent.toLowerCase().includes(e.target.value.toLowerCase());});
  $('#import-template-select')?.addEventListener('change',async e=>{const template=context().templates.find(t=>t.id===e.target.value);if(template){wizard.options={...structuredClone(template.options),perFile:{}};wizard.preview=null;await preflight();}});
  $('#import-files')?.addEventListener('change',async e=>{wizard.assets=[...e.target.files].map(file=>({file}));draw();await preflight();});
  $('#import-linked-picker')?.addEventListener('click',async()=>{try{const handles=await window.showOpenFilePicker({multiple:true});wizard.assets=await Promise.all(handles.map(async handle=>({handle,file:await handle.getFile()})));wizard.options.linkOriginals=true;draw();await preflight();}catch(error){if(error.name!=='AbortError')$('#import-error').textContent=error.message;}});
  $('#cancel-import')?.addEventListener('click',async()=>{wizard.controller.abort();if(wizard.record&&project.storage==='cloud')await cancelNative(project,wizard.record.id).catch(e=>host.toast(e.message));wizard.busy=false;draw();});
  $('#ingestion-form').onsubmit=async event=>{event.preventDefault();if(wizard.busy)return;capture();const error=$('#import-error');if(wizard.step===0&&!visibleFamily(families.find(f=>f.id===wizard.family),project)){error.textContent='Choose a data type enabled for this project workflow.';return;}if(wizard.step===1&&!wizard.assets.length){error.textContent='Choose at least one source file.';return;}if(wizard.assets.some(a=>a.file.size>10*1024**3||!a.file.size)){error.textContent='Each source must be non-empty and no larger than 10 GiB.';return;}if(wizard.step===3){const h=Number(wizard.options.headerRow);if(!Number.isInteger(h)||h<1){error.textContent='Header row must be a positive whole number.';return;}for(const role of ['md','inclination','azimuth'])if(wizard.family==='deviation'&&wizard.options.surveyMethod!=='coordinates'&&!wizard.options.mapping[role]&&wizard.preview){error.textContent='Map measured depth, inclination and azimuth before continuing.';return;}}
   if(wizard.step<4){wizard.step++;draw();return;}if(wizard.step===4){wizard.step=5;wizard.busy=true;draw();try{const onProgress=message=>{if($('#import-feedback'))$('#import-feedback').textContent=message;};const seen=new Set((workspace.files||[]).map(f=>f.sha256).filter(Boolean));const accepted=[];for(const asset of wizard.assets){if(asset.existingId){accepted.push(asset);continue;}onProgress('Checking fingerprint · '+asset.file.name);const digest=await browserRead(asset.file,wizard.family,{fingerprintOnly:true},{signal:wizard.controller.signal,onProgress:p=>onProgress('Checking fingerprint · '+asset.file.name+' · '+Math.round(p.loaded/p.total*100)+'%')});if(seen.has(digest.sha256)){host.toast(asset.file.name+': exact duplicate skipped.');continue;}seen.add(digest.sha256);accepted.push(asset);}if(!accepted.length)throw new Error('All selected sources are exact duplicates already retained in this project.');if(project.storage==='cloud'){wizard.record=await nativeImport(project,accepted,wizard.family,wizard.options,{signal:wizard.controller.signal,onProgress,onSession:record=>{wizard.record=record;}});await host.reload();}else{wizard.record=await importLocal(project,workspace,accepted,wizard.family,wizard.options,{signal:wizard.controller.signal,onProgress,onSave:async()=>{host.save();await host.flush();}});}wizard.busy=false;draw();}catch(e){wizard.busy=false;draw();$('#import-error').textContent=e.message;await host.reload().catch(()=>{});}}
  };
  if(wizard.step===5&&wizard.record&&!wizard.busy)bindRecordActions(wizard.record,project,()=>{draw();});
 }
 draw();
}
function recordView(record){const blocking=!(record.datasets||[]).some(d=>!d.issues?.some(i=>i.severity==='blocking'));return `<div class="import-result-head">${pill(record.status)}<span>${record.datasets?.length||0} datasets found</span></div>${issuesView(record.issues||[])}<div class="import-dataset-list">${(record.datasets||[]).map(d=>`<label class="layer"><input type="checkbox" data-select-dataset="${esc(d.id)}" ${d.issues?.some(i=>i.severity==='blocking')?'':'checked'}>Include dataset</label><button type="button" data-review-dataset="${esc(d.id)}"><span><strong>${esc(d.name)}</strong><small>${Number(d.rowCount||0).toLocaleString()} records · ${d.columns?.length||0} columns</small></span>Preview →</button>`).join('')}</div>${!record.committedAt&&['awaiting confirmation','retained/unresolved'].includes(record.status)?`<label class="layer"><input type="checkbox" id="ack-import-warnings">I reviewed the remaining warnings. Imported data is not scientifically approved.</label><label class="field">Save mapping template <small>Optional</small><input id="import-template-name" maxlength="100" placeholder="For example: deviation survey export"></label><button type="button" class="primary" id="commit-import" ${blocking?'disabled':''}>Confirm import</button>${blocking?'<p class="sub">Originals are retained. Resolve the blocking format or mapping issues before activation.</p>':''}`:''}`;}
function bindRecordActions(record,project,onComplete){
 const commitButton=$('#commit-import');
 if(commitButton){
  const previous=(context().datasets||[]).filter(d=>d.active!==false);
  if(previous.length){const field=document.createElement('label');field.className='field';field.innerHTML='Version handling<select id="import-replace"><option value="">Create independent datasets (recommended)</option>'+previous.map(d=>'<option value="'+esc(d.id)+'">Replace active: '+esc(d.name)+'</option>').join('')+'</select><small>Replacement preserves the previous version. Select one new dataset.</small>';commitButton.before(field);}
  if(project.storage==='cloud'){const edit=document.createElement('button');edit.type='button';edit.textContent='Edit mapping / references';edit.onclick=()=>editNativeMapping(record,project);commitButton.before(edit);}
 }
 $('#commit-import')?.addEventListener('click',async()=>{try{if(record.issues?.length&&!$('#ack-import-warnings').checked)throw new Error('Acknowledge the remaining warnings before confirming.');$('#commit-import').disabled=true;const name=$('#import-template-name').value.trim(),replaceId=$('#import-replace')?.value||null;if(replaceId&&!confirm('Replace this active dataset? Its previous version will remain retained.')){$('#commit-import').disabled=false;return;}const selection={selected_dataset_ids:[...document.querySelectorAll('[data-select-dataset]:checked')].map(e=>e.dataset.selectDataset),selected_columns:{}};document.querySelectorAll('[data-select-column]').forEach(input=>{const id=input.dataset.columnDataset;selection.selected_columns[id]||=[];if(input.checked)selection.selected_columns[id].push(input.dataset.selectColumn);});if(project.storage==='cloud'){Object.assign(record,await commitNative(project,record,true,name,replaceId,selection));await host.reload();await refreshData(true);}else Object.assign(record,await commitLocal(host.getState(),record,{templateName:name,replaceId,selection,onSave:async()=>{host.save();await host.flush();}}));onComplete();}catch(error){host.toast(error.message);if($('#commit-import'))$('#commit-import').disabled=false;}});
 document.querySelectorAll('[data-review-dataset]').forEach(button=>button.onclick=async()=>{try{const d=record.datasets.find(d=>d.id===button.dataset.reviewDataset),preview=project.storage==='cloud'?await nativePreview(project,record.id,d.id):d;const panel=document.createElement('section');panel.className='inline-dataset-preview';panel.innerHTML='<h3>'+esc(d.name)+'</h3>'+previewTable(preview)+'<details><summary>Select active columns / channels</summary>'+preview.columns.map(c=>'<label class="layer"><input type="checkbox" data-select-column="'+esc(c.id)+'" data-column-dataset="'+esc(d.id)+'" checked>'+esc(c.mnemonic)+' · '+esc(c.effectiveUnit||c.unit||'unit unconfirmed')+'</label>').join('')+'</details>';button.after(panel);button.disabled=true;}catch(error){host.toast(error.message);}});
}
async function editNativeMapping(record,project){
 try{
  const dataset=record.datasets?.[0];const preview=dataset?await nativePreview(project,record.id,dataset.id):{columns:[]};
  const options=structuredClone(record.options||{}),refs=options.references||{},mapping=options.mapping||{};
  const field=(name,label,value='')=>'<label class="field">'+esc(label)+'<input name="'+esc(name)+'" value="'+esc(value)+'"></label>';
  host.modal('Review source interpretation','<p>Update the interpretation of retained originals. Reinspection creates new artifacts without transferring the originals again.</p><form id="native-mapping"><div class="form-grid">'+(mappingRoles[record.family]||[]).map(role=>'<label class="field">'+esc(labels[role])+'<select name="mapping:'+esc(role)+'"><option value="">Unconfirmed</option>'+preview.columns.map((c,i)=>'<option value="'+i+'" '+(String(mapping[role])===String(i)?'selected':'')+'>'+esc(c.mnemonic)+' · '+esc(c.unit||'unit unknown')+'</option>').join('')+'</select></label>').join('')+['depthReference','depthUnit','northReference','angleUnit','timeConvention','timeUnit','verticalDatum','crs','coordinateOrder','domain'].map(k=>field('ref:'+k,k.replace(/([A-Z])/g,' $1'),refs[k])).join('')+field('hdfPaths','HDF5 dataset paths (comma separated)',(options.hdfPaths||[]).join(','))+field('frames','Frame names (comma separated; blank = all)',(options.frames||[]).join(','))+'</div><details><summary>Column units</summary><div class="form-grid">'+preview.columns.map((c,i)=>field('unit:'+i,c.mnemonic+' · source '+(c.unit||'unknown'),options.units?.[String(i)])).join('')+'</div></details><p id="native-mapping-error" role="alert"></p><button class="primary" type="submit">Save & reinspect</button></form>');
  $('#native-mapping').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;try{const values=new FormData(form);options.references||={};options.mapping||={};options.units||={};for(const [key,value]of values){if(key.startsWith('ref:'))options.references[key.slice(4)]=String(value).trim();if(key.startsWith('mapping:'))options.mapping[key.slice(8)]=String(value);if(key.startsWith('unit:'))options.units[key.slice(5)]=String(value).trim();}for(const key of ['frames','hdfPaths'])options[key]=String(values.get(key)||'').split(',').map(v=>v.trim()).filter(Boolean);await api(`/api/projects/${project.id}/imports/${record.id}/configuration`,{method:'PUT',body:{revision:record.revision,options}});await api(`/api/projects/${project.id}/imports/${record.id}/inspect`,{method:'POST',body:{}});$('#dialog').close();await refreshData(true);host.toast('Reinspection started. Follow progress in Import history.');}catch(error){$('#native-mapping-error').textContent=error.message;button.disabled=false;}};
 }catch(error){host.toast(error.message);}
}
async function reviewImport(id){let record=context().imports.find(r=>r.id===id);if(!record)return;const project=host.getProject();host.modal('Import details',`<h3>${esc(nameOf(record.family))}</h3>${recordView(record)}${['stored','failed'].includes(record.status)?'<button id="retry-inspection">Retry native inspection</button>':''}${record.status==='uploading'?'<p class="sub">Reselect the same original files below to resume unfinished transfers.</p><input id="resume-import-files" type="file" multiple>':''}${!record.committedAt&&record.status!=='cancelled'?'<button id="cancel-stored-import">Cancel import · keep retained originals</button>':''}`);bindRecordActions(record,project,()=>{host.modal('Import recorded','<p>The original evidence and reader outcome are retained in this project.</p>');host.render();});$('#retry-inspection')?.addEventListener('click',async()=>{try{await api(`/api/projects/${project.id}/imports/${record.id}/inspect`,{method:'POST',body:{}});await refreshData(true);host.toast('Inspection started. Reopen Import history to check progress.');$('#dialog').close();}catch(error){host.toast(error.message);}});$('#resume-import-files')?.addEventListener('change',async e=>{try{for(const asset of record.assets.filter(a=>a.state!=='stored')){const file=[...e.target.files].find(f=>f.name===asset.name&&f.size===asset.size);if(!file)throw new Error('Select the same file name and size for every incomplete source.');const transfer=await api(`/api/projects/${project.id}/imports/${record.id}/upload/${asset.id}`,{method:'POST',body:{}});if(!transfer.stored)await resumableUpload(file,transfer.upload_url);await api(`/api/projects/${project.id}/imports/${record.id}/complete/${asset.id}`,{method:'POST',body:{}});}await api(`/api/projects/${project.id}/imports/${record.id}/inspect`,{method:'POST',body:{}});await refreshData(true);$('#dialog').close();}catch(error){host.toast(error.message);}});$('#cancel-stored-import')?.addEventListener('click',async()=>{try{if(project.storage==='cloud')await cancelNative(project,record.id);else{record.status='cancelled';host.save();await host.flush();}await refreshData(true);$('#dialog').close();host.render();}catch(error){host.toast(error.message);}});}
